"""Device / pairing service (Phase 16).

Everything about the LAN device registry lives here:

* the **pairing code** (owner Q1: mandatory 6 digits) — generated by an
  admin, validated in constant time, short lived, kept in process memory
  only because Phase 16 deliberately has no settings table;
* **rate limiting** for ``POST /devices/pair`` (5/min per IP, 10/min
  global) — in memory, single worker, documented as such;
* the **one-time device token** delivery window between admin approval and
  the client's next poll — only a SHA-256 hash is persisted;
* the four auditable transitions (pair / approve / reject / revoke).

Heartbeats and ``last_seen_at`` updates are NEVER audited (§18) and the
pairing code / device token / PIN / JWT are NEVER placed in an audit row.
"""

from __future__ import annotations

import secrets
import threading
import time
import uuid
from datetime import datetime, timezone

import structlog

from app.core.exceptions import (
    AppError,
    ConflictError,
    NotFoundError,
)
from app.core.rate_limit import SlidingWindowLimiter as _SlidingWindowLimiter
from app.core.rate_limit import reset_rate_limiters
from app.core.security import hash_token
from app.models.audit import AuditLog
from app.models.device import Device
from app.models.enums import AuditAction, DeviceStatus
from app.repositories.device import DeviceRepository
from app.services.base import BaseService

logger = structlog.get_logger(__name__)

PAIRING_CODE_TTL_SECONDS = 600
TOKEN_DELIVERY_TTL_SECONDS = 600
RATE_WINDOW_SECONDS = 60
PAIR_LIMIT_PER_IP = 5
PAIR_LIMIT_GLOBAL = 10


# ---------------------------------------------------------------------------
# Errors
# ---------------------------------------------------------------------------


class DeviceRequiredError(AppError):
    """X-Device-ID / X-Device-Token headers are missing (LAN_MODE on).

    Step A §12 contract: 401 UNAUTHORIZED — no machine identity was offered
    at all (as opposed to a presented device being refused, which is 403).
    """

    code = "device_required"
    status_code = 401
    message_key = "errors.deviceRequired"


class DeviceNotPairedError(AppError):
    """The presented device is unknown, pending or rejected.

    Step A §12 contract: 403 FORBIDDEN — the *device* is not authorised for
    this server, while the caller's own session may be perfectly valid.
    """

    code = "device_not_paired"
    status_code = 403
    message_key = "errors.deviceNotPaired"


class DeviceRevokedError(AppError):
    """The presented device used to be approved and has been revoked.

    Step A §12 contract: 403 FORBIDDEN.
    """

    code = "device_revoked"
    status_code = 403
    message_key = "errors.deviceRevoked"


class DeviceTokenInvalidError(AppError):
    """Approved device but the token hash does not match.

    Same canonical status as every other ``device_not_paired`` rejection.
    """

    code = "device_not_paired"
    status_code = 403
    message_key = "errors.deviceNotPaired"


class PairingCodeInvalidError(AppError):
    code = "PAIRING_CODE_INVALID"
    status_code = 401
    message_key = "errors.pairingCodeInvalid"


class PairingRateLimitedError(AppError):
    code = "PAIRING_RATE_LIMITED"
    status_code = 429
    message_key = "errors.pairingRateLimited"


class DeviceAlreadyPairedError(AppError):
    code = "DEVICE_ALREADY_PAIRED"
    status_code = 409
    message_key = "errors.deviceAlreadyPaired"


# ---------------------------------------------------------------------------
# Process-local state (single worker; no new tables in Phase 16)
# ---------------------------------------------------------------------------


class _PairingCodeState:
    """The current 6-digit admin code plus its expiry."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self.code: str | None = None
        self.generated_at: datetime | None = None
        self.expires_at: datetime | None = None

    def rotate(self) -> tuple[str, datetime, datetime]:
        now = datetime.now(timezone.utc)
        code = f"{secrets.randbelow(1_000_000):06d}"
        expires = now.timestamp() + PAIRING_CODE_TTL_SECONDS
        expires_at = datetime.fromtimestamp(expires, tz=timezone.utc)
        with self._lock:
            self.code = code
            self.generated_at = now
            self.expires_at = expires_at
        return code, now, expires_at

    def current(self) -> tuple[str, datetime, datetime] | None:
        with self._lock:
            code, generated, expires = self.code, self.generated_at, self.expires_at
        if code is None or generated is None or expires is None:
            return None
        if datetime.now(timezone.utc) >= expires:
            return None
        return code, generated, expires

    def matches(self, candidate: str) -> bool:
        current = self.current()
        if current is None:
            return False
        return secrets.compare_digest(current[0], candidate)

    def clear(self) -> None:
        with self._lock:
            self.code = None
            self.generated_at = None
            self.expires_at = None


class _TokenVault:
    """One-time delivery window for freshly minted device tokens.

    Only the APPROVED device's token lives here and only until the client
    polls it (or the window closes). Nothing is ever written to disk or
    logged, so the plaintext token exists exactly once, in flight.
    """

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._tokens: dict[str, tuple[str, float]] = {}

    def put(self, pairing_id: uuid.UUID, token: str) -> None:
        with self._lock:
            self._tokens[str(pairing_id)] = (token, time.monotonic())

    def take(self, pairing_id: uuid.UUID) -> str | None:
        key = str(pairing_id)
        now = time.monotonic()
        with self._lock:
            entry = self._tokens.get(key)
            if entry is None:
                return None
            token, issued = entry
            if now - issued > TOKEN_DELIVERY_TTL_SECONDS:
                self._tokens.pop(key, None)
                return None
            self._tokens.pop(key, None)
            return token

    def drop(self, pairing_id: uuid.UUID) -> None:
        with self._lock:
            self._tokens.pop(str(pairing_id), None)


pairing_codes = _PairingCodeState()
pair_limiter_ip = _SlidingWindowLimiter(PAIR_LIMIT_PER_IP, RATE_WINDOW_SECONDS)
pair_limiter_global = _SlidingWindowLimiter(PAIR_LIMIT_GLOBAL, RATE_WINDOW_SECONDS)
token_vault = _TokenVault()


def reset_process_state() -> None:
    """Testing seam: forget every in-memory process singleton.

    Covers the Phase 16 pairing state and, since §17.7, the app-wide
    rate-limit windows too — both are process-global like this one.
    """
    pairing_codes.clear()
    token_vault._tokens.clear()  # noqa: SLF001 - test seam
    pair_limiter_ip.clear()
    pair_limiter_global.clear()
    reset_rate_limiters()


# ---------------------------------------------------------------------------
# Service
# ---------------------------------------------------------------------------


class DeviceService(BaseService):
    """Device registry + pairing workflow."""

    def __init__(self, db):
        super().__init__(db)
        self.repo = DeviceRepository(db)

    # -- pairing code ------------------------------------------------------

    def rotate_pairing_code(self) -> tuple[str, datetime, datetime]:
        return pairing_codes.rotate()

    def current_pairing_code(self) -> tuple[str, datetime, datetime] | None:
        return pairing_codes.current()

    # -- handshake ---------------------------------------------------------

    def request_pairing(
        self,
        *,
        device_id: str,
        display_name: str,
        pairing_code: str,
        client_version: str | None,
        client_ip: str | None,
    ) -> Device:
        """Create (or re-open) a ``devices`` row in ``pending``.

        Re-pairing an existing machine updates the SAME row — the
        ``device_id`` is immutable and unique (owner Q9), so a revoked or
        rejected till simply goes back to ``pending`` for a fresh human
        decision instead of duplicating.
        """
        if not pairing_codes.matches(pairing_code):
            raise PairingCodeInvalidError(
                message="Invalid or expired pairing code",
            )

        existing = self.repo.get_by_device_id(device_id)

        if existing is not None and existing.status == DeviceStatus.APPROVED.value:
            raise DeviceAlreadyPairedError(
                message="This device is already approved; revoke it first",
                details={"device_id": device_id},
            )

        with self.transaction():
            if existing is not None:
                device = existing
                device.display_name = display_name
                device.client_version = client_version
                device.status = DeviceStatus.PENDING.value
                device.pairing_id = uuid.uuid4()
                device.requested_ip = client_ip
                device.token_hash = None
                device.rejected_at = None
                device.revoked_at = None
                device.approved_at = None
                device.approved_by = None
            else:
                device = Device(
                    device_id=device_id,
                    pairing_id=uuid.uuid4(),
                    display_name=display_name,
                    status=DeviceStatus.PENDING.value,
                    client_version=client_version,
                    requested_ip=client_ip,
                )
                self.repo.create(device)
            token_vault.drop(device.pairing_id)
            self._audit(
                AuditAction.DEVICE_PAIR,
                device,
                f"pairing requested for {device.display_name}",
                user_id=None,
                ip_address=client_ip,
            )
        return device

    def poll_pairing(self, pairing_id: uuid.UUID) -> tuple[Device, str | None, bool]:
        """Return ``(device, one_time_token_or_None, token_unavailable)``."""
        device = self.repo.get_by_pairing_id(pairing_id)
        if device is None:
            raise NotFoundError(
                message="Pairing request not found",
                details={"pairing_id": str(pairing_id)},
            )

        if device.status != DeviceStatus.APPROVED.value:
            return device, None, False

        token = token_vault.take(pairing_id)
        if token is not None:
            return device, token, False
        # Approved but the one-time window is gone (restart, TTL, second
        # poll): the stored hash is the only proof left, so the client must
        # re-pair. The flag lets the UI say that instead of hanging.
        return device, None, True

    # -- admin decisions ---------------------------------------------------

    def approve(
        self,
        device_pk: uuid.UUID,
        actor_id: uuid.UUID,
        actor_ip: str | None = None,
    ) -> tuple[Device, str]:
        device = self._require(device_pk)
        if device.status == DeviceStatus.APPROVED.value:
            raise ConflictError(
                message="Device is already approved",
                details={"device_id": device.device_id},
            )
        if device.status == DeviceStatus.REVOKED.value:
            raise ConflictError(
                message="A revoked device must be re-paired before approval",
                details={"device_id": device.device_id},
            )

        token = secrets.token_urlsafe(32)
        now = datetime.now(timezone.utc)
        with self.transaction():
            device.status = DeviceStatus.APPROVED.value
            device.token_hash = hash_token(token)
            device.approved_at = now
            device.approved_by = actor_id
            device.rejected_at = None
            device.revoked_at = None
            self._audit(
                AuditAction.DEVICE_APPROVE,
                device,
                f"device approved: {device.display_name}",
                user_id=actor_id,
                ip_address=actor_ip,
            )
        token_vault.put(device.pairing_id, token)
        return device, token

    def deny(
        self,
        device_pk: uuid.UUID,
        actor_id: uuid.UUID,
        reason: str | None,
        actor_ip: str | None = None,
    ) -> Device:
        device = self._require(device_pk)
        if device.status == DeviceStatus.APPROVED.value:
            raise ConflictError(
                message="An approved device must be revoked, not denied",
                details={"device_id": device.device_id},
            )
        with self.transaction():
            device.status = DeviceStatus.REJECTED.value
            device.rejected_at = datetime.now(timezone.utc)
            device.token_hash = None
            device.approved_at = None
            device.approved_by = None
            detail = f"device rejected: {device.display_name}"
            if reason:
                detail = f"{detail} — {reason}"
            self._audit(
                AuditAction.DEVICE_REJECT,
                device,
                detail,
                user_id=actor_id,
                ip_address=actor_ip,
            )
        token_vault.drop(device.pairing_id)
        return device

    def revoke(
        self,
        device_pk: uuid.UUID,
        actor_id: uuid.UUID,
        reason: str | None,
        actor_ip: str | None = None,
    ) -> Device:
        device = self._require(device_pk)
        if device.status != DeviceStatus.APPROVED.value:
            raise ConflictError(
                message="Only an approved device can be revoked",
                details={"device_id": device.device_id, "status": device.status},
            )
        with self.transaction():
            device.status = DeviceStatus.REVOKED.value
            device.revoked_at = datetime.now(timezone.utc)
            # Clear the credential so the stored hash can never match again.
            device.token_hash = None
            detail = f"device revoked: {device.display_name}"
            if reason:
                detail = f"{detail} — {reason}"
            self._audit(
                AuditAction.DEVICE_REVOKE,
                device,
                detail,
                user_id=actor_id,
                ip_address=actor_ip,
            )
        token_vault.drop(device.pairing_id)
        return device

    # -- reads -------------------------------------------------------------

    def list_devices(self) -> tuple[list[Device], int]:
        items, total = self.repo.list_all()
        return list(items), total

    def get_by_device_id(self, device_id: str) -> Device | None:
        return self.repo.get_by_device_id(device_id)

    def count_devices(self) -> int:
        return self.repo.count()

    # -- helpers -----------------------------------------------------------

    def _require(self, device_pk: uuid.UUID) -> Device:
        device = self.repo.get_by_id(device_pk)
        if device is None:
            raise NotFoundError(
                message="Device not found", details={"device_id": str(device_pk)}
            )
        return device

    def _audit(
        self,
        action: AuditAction,
        device: Device,
        details: str,
        *,
        user_id: uuid.UUID | None = None,
        ip_address: str | None = None,
    ) -> None:
        """Write ONE audit row.

        Never carries a pairing code, a device token, a PIN or a JWT (§18),
        and never runs for a heartbeat / last_seen update.
        """
        try:
            self.db.add(
                AuditLog(
                    user_id=user_id,
                    action=action.value,
                    entity_type="device",
                    entity_id=device.id,
                    details=details,
                    ip_address=ip_address,
                    device_id=device.device_id,
                )
            )
        except Exception as exc:  # pragma: no cover - audit must not break flow
            logger.error("device_audit_failed", error=str(exc))
